-- Seed SÓ para o banco local: jogadores fictícios para testar a busca e o perfil público.
-- Requer as migrations aplicadas (npm run db:migrate:local).
-- Uso: npm run db:seed:local   (pode rodar de novo: apaga e recria esses registros)
-- Nunca rode com --remote.

DELETE FROM ratings WHERE avaliado_id LIKE '00000000-0000-4000-8000-%';
DELETE FROM invites WHERE de_user LIKE '00000000-0000-4000-8000-%' OR para_user LIKE '00000000-0000-4000-8000-%';
DELETE FROM profiles WHERE user_id LIKE '00000000-0000-4000-8000-%';
DELETE FROM users WHERE id LIKE '00000000-0000-4000-8000-%';

